import { useCallback, useMemo, useState } from "react";
import { AgGridProvider, AgGridReact } from "ag-grid-react";
import type { ColDef, GetDataPath } from "ag-grid-community";
import { AllEnterpriseModule } from "ag-grid-enterprise";

const modules = [AllEnterpriseModule];

interface FileRow {
  path: string[];
  size?: number;
  modified?: string;
}

export function FileTree() {
  const [rowData] = useState<FileRow[]>([
    { path: ["Documents"] },
    { path: ["Documents", "Contracts"] },
    { path: ["Documents", "Contracts", "nda.pdf"], size: 120, modified: "2026-09-12" },
    { path: ["Documents", "Contracts", "msa.pdf"], size: 340, modified: "2026-08-03" },
    { path: ["Documents", "budget.xlsx"], size: 88, modified: "2026-09-30" },
  ]);

  const columnDefs = useMemo<ColDef<FileRow>[]>(() => [
    { field: "size", headerName: "Size (KB)", aggFunc: "sum" }, // group rows show the sum of their children
    { field: "modified", filter: "agDateColumnFilter", cellDataType: "dateString" },
  ], []);

  const autoGroupColumnDef = useMemo<ColDef<FileRow>>(() => ({
    headerName: "Name", minWidth: 280, filter: "agTextColumnFilter",
  }), []);

  // Each row's position in the tree, as an array of keys
  const getDataPath = useCallback<GetDataPath<FileRow>>((data) => data.path, []);

  return (
    <AgGridProvider modules={modules}>
      <div style={{ height: 400 }}>
        <AgGridReact<FileRow>
          rowData={rowData}
          columnDefs={columnDefs}
          autoGroupColumnDef={autoGroupColumnDef}
          treeData
          getDataPath={getDataPath}
          groupDefaultExpanded={-1}
        />
      </div>
    </AgGridProvider>
  );
}
